import{d as n,y as b,z as r,c as o,a,F as p,s as u,b as h,r as f,o as v,C as g,t as y,_ as m}from"./index-CVlekhhx.js";const _={class:"page"},D={class:"container"},B={class:"docs-layout"},C={class:"toc glass"},k=["onClick"],x=n({__name:"Docs",setup(I){const e=[{id:"drive",title:"连接网盘"},{id:"libraries",title:"媒体库管理"},{id:"scrape",title:"刮削与工作台"},{id:"tree",title:"115 目录树更新"},{id:"player",title:"播放器接入"},{id:"settings",title:"定时与设置"},{id:"faq",title:"常见问题"}],s=f(e[0].id);function c(t){var d;s.value=t,(d=document.getElementById(t))==null||d.scrollIntoView({behavior:"smooth",block:"start"})}let l=null;return b(()=>{l=new IntersectionObserver(t=>{for(const d of t)d.isIntersecting&&(s.value=d.target.id)},{rootMargin:"-96px 0px -70% 0px",threshold:0});for(const t of e){const d=document.getElementById(t.id);d&&l.observe(d)}}),r(()=>l==null?void 0:l.disconnect()),(t,d)=>(v(),o("main",_,[a("div",D,[d[2]||(d[2]=a("div",{class:"page-head"},[a("div",null,[a("h1",{class:"page-title"},"文档"),a("p",{class:"page-sub"},"CloudFlow 使用教程：从接入网盘到播放器接入的完整流程")])],-1)),a("div",B,[a("aside",C,[d[0]||(d[0]=a("div",{class:"toc-title"},"目录",-1)),(v(),o(p,null,u(e,i=>a("button",{key:i.id,type:"button",class:g(["toc-item",{"is-active":s.value===i.id}]),onClick:M=>c(i.id)},y(i.title),11,k)),64))]),d[1]||(d[1]=h('<article class="doc-content" data-v-9da044d7><section id="drive" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>连接网盘</h2><h3 data-v-9da044d7>115 网盘</h3><ol class="steps" data-v-9da044d7><li data-v-9da044d7>打开 <code data-v-9da044d7>api.oplist.org</code> →「115 网盘 · 验证登录」→ 勾选<b data-v-9da044d7>「使用 OpenList 提供的参数」</b>；</li><li data-v-9da044d7>完成授权后复制<b data-v-9da044d7>访问令牌</b>与<b data-v-9da044d7>刷新令牌</b>，粘贴到 CloudFlow「网盘 → 115 网盘」；</li><li data-v-9da044d7>令牌过期会自动续期；失效后在账号卡片点「重新连接 / 更换令牌」原地恢复，已入库数据全部保留。</li></ol><p class="tip" data-v-9da044d7>支持多账号：每次粘贴令牌新增一个账号，各账号目录可添加到同一个媒体库，互不干扰。</p><h3 data-v-9da044d7>WebDAV</h3><p data-v-9da044d7>填写地址、账号、密码即可；可选「自定义直链源」（播放地址改指向该来源）。WebDAV 不需要目录树，扫描直接遍历。</p></section><section id="libraries" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>媒体库管理</h2><ul class="bullets" data-v-9da044d7><li data-v-9da044d7><b data-v-9da044d7>库类型</b>：电影 / 电视剧 / 混合内容 —— 决定刮削的搜索范围与组织方式；</li><li data-v-9da044d7><b data-v-9da044d7>添加目录</b>：在「网盘」页浏览到目标文件夹，选中媒体库后「添加当前目录到媒体库」；</li><li data-v-9da044d7><b data-v-9da044d7>刮削全部</b>：媒体库弹窗里一键更新所有目录（入库 + 自动匹配）；</li><li data-v-9da044d7><b data-v-9da044d7>刷新全部</b>：页头一键按库顺序刷新所有媒体库，刷完一个库等 5 秒再刷下一个（防风控）；</li><li data-v-9da044d7><b data-v-9da044d7>自动扫描</b>：目录开关开启后按设置页 cron 表达式定时更新；</li><li data-v-9da044d7><b data-v-9da044d7>失效条目</b>：网盘里已删除文件的空壳条目，一键清理（连海报 / 剧照一起删）。</li></ul></section><section id="scrape" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>刮削与工作台</h2><ul class="bullets" data-v-9da044d7><li data-v-9da044d7><b data-v-9da044d7>自动识别</b>：解析文件名 / 目录名中的中英文标题、年份、季集（<code data-v-9da044d7>S01E02</code>、<code data-v-9da044d7>1x02</code>、集号尾缀等）；</li><li data-v-9da044d7><b data-v-9da044d7>一键自动匹配</b>：多路并行、失败自动重试、列表实时刷新，<b data-v-9da044d7>自动跑到底</b>，无需守着点；刷新页面会自动接管续刮，进度不丢；结束汇报识别 / 未识别 / 剩余量；</li><li data-v-9da044d7><b data-v-9da044d7>电视剧按「季 / 文件夹」整夹绑定</b>：一季一次绑完，集号猜不出时按文件名顺序补；</li><li data-v-9da044d7><b data-v-9da044d7>手动匹配</b>：工作台点「手动匹配 / 文件夹刮削」，搜 TMDB 重新绑定；</li><li data-v-9da044d7><b data-v-9da044d7>重新匹配</b>：详情页纠正刮错（已锁定字段不覆盖，文件绑定不变）；</li><li data-v-9da044d7><b data-v-9da044d7>限流模式</b>（设置页）：Cloudflare 部署保持开启（防风控 / 操作预算打爆）；Docker 自部署可关闭，速度提升数倍。</li></ul></section><section id="tree" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>115 目录树更新（防风控）</h2><p data-v-9da044d7>115 库的更新走官方「导出目录树」机制：服务端生成目录树文本 → 程序解析入库。每次更新只有十几次网盘请求，<b data-v-9da044d7>不会触发风控</b>（逐目录遍历扫库才会）。</p><ol class="steps" data-v-9da044d7><li data-v-9da044d7>点「立即更新」—— 自动导出可用时全自动；</li><li data-v-9da044d7>提示「自动导出不可用」时：在 115 客户端 / 网页<b data-v-9da044d7>长按目标文件夹 → 生成文件目录树</b>（输出 txt 落在网盘根），再点「立即更新」即可，程序自动导入；</li><li data-v-9da044d7>更新完成后照常自动刮削。</li></ol><p class="tip" data-v-9da044d7>提示「未找到目录树输出文件」= 生成还没出来：稍后重试，或手动「生成文件目录树」后更新。</p></section><section id="player" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>播放器接入</h2><ul class="bullets" data-v-9da044d7><li data-v-9da044d7>协议：<b data-v-9da044d7>Jellyfin 兼容</b>；服务地址填 <code data-v-9da044d7>http://主机:8787/jellyfin</code>（注意结尾 <code data-v-9da044d7>/jellyfin</code>）；</li><li data-v-9da044d7>支持网易爆米花、VidHub 等支持 Jellyfin 的播放器；</li><li data-v-9da044d7>播放为 <b data-v-9da044d7>302 直链</b>：视频流量不经过服务器，直链与播放器 User-Agent 绑定透传；</li><li data-v-9da044d7>蓝光原盘自动定位正片（<code data-v-9da044d7>BDMV/STREAM</code> 下最大的 m2ts），播放器直接播正片。</li></ul></section><section id="settings" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>定时与设置</h2><ul class="bullets" data-v-9da044d7><li data-v-9da044d7><b data-v-9da044d7>TMDB API Key / 语言</b>：刮削元数据与海报来源、首选语言；</li><li data-v-9da044d7><b data-v-9da044d7>刮削代理</b>：大陆网络需要（TMDB 无法直连）；仅 TMDB 请求走代理，网盘不走；</li><li data-v-9da044d7><b data-v-9da044d7>定时扫描</b>：5 字段 cron 表达式（默认每天 7–23 点每 4 小时），仅对开启「自动扫描」的目录生效；</li><li data-v-9da044d7><b data-v-9da044d7>视频扩展名列表</b>：扫描 / 导入只处理这些扩展名；</li><li data-v-9da044d7><b data-v-9da044d7>限流模式</b>：见「刮削与工作台」；</li><li data-v-9da044d7><b data-v-9da044d7>备案号</b>：填写后显示在页脚。</li></ul></section><section id="faq" class="doc-section" data-v-9da044d7><h2 data-v-9da044d7>常见问题</h2><table class="doc-table" data-v-9da044d7><tbody data-v-9da044d7><tr data-v-9da044d7><td data-v-9da044d7>海报墙没有内容</td><td data-v-9da044d7>先连接网盘、把目录添加到媒体库并「立即更新」；未识别的文件到「刮削」页一键自动匹配或手动匹配。</td></tr><tr data-v-9da044d7><td data-v-9da044d7>刮削速度慢 / 想提速</td><td data-v-9da044d7>设置页关闭「限流模式」（Docker 自部署适用；Cloudflare 保持开启防风控）。</td></tr><tr data-v-9da044d7><td data-v-9da044d7>115 令牌失效 / 连不上</td><td data-v-9da044d7>115 网盘页点「更换令牌 / 重新连接」，到 api.oplist.org 重新获取粘贴即可，数据保留。</td></tr><tr data-v-9da044d7><td data-v-9da044d7>更新提示「自动导出不可用 / 请重新登录」</td><td data-v-9da044d7>目录树自动导出接口不接受令牌鉴权（浏览/播放不受影响）—— 在 115 端手动生成目录树后再更新。</td></tr><tr data-v-9da044d7><td data-v-9da044d7>刮错条目</td><td data-v-9da044d7>详情页「重新匹配」，搜索正确条目（已锁定字段不覆盖）。</td></tr><tr data-v-9da044d7><td data-v-9da044d7>云端删了文件，海报墙还有残留</td><td data-v-9da044d7>更新后会标记文件丢失；到「媒体库管理 → 失效条目」一键清理。</td></tr><tr data-v-9da044d7><td data-v-9da044d7>播放器连不上 / 无法播放</td><td data-v-9da044d7>地址要带 <code data-v-9da044d7>/jellyfin</code> 后缀；查看部署日志里的 <code data-v-9da044d7>[jellyfin]</code> 请求记录定位。</td></tr></tbody></table></section></article>',1))])])]))}}),E=m(x,[["__scopeId","data-v-9da044d7"]]);export{E as default};
